class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        dp = [[1] * 300 for _ in range(301)]
        best = [[1] * 300 for _ in range(301)]
        seen = []

        for x in nums:
            if not seen:
                seen.append(x)
                continue

            row = dp[x]
            for y in set(seen):
                d = abs(x - y)
                row[d] = max(row[d], best[y][d] + 1)

            mx = 1
            for d in range(299, -1, -1):
                mx = max(mx, row[d])
                best[x][d] = mx

            seen.append(x)

        return max(best[x][0] for x in set(nums))
